+function getApiBase(): string {
+  const base = process.env.NEXT_PUBLIC_API_BASE_URL;
+  if (!base) {
+    throw new Error("NEXT_PUBLIC_API_BASE_URL is required for workflow-backend API calls");
+  }
+  return base;
